using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using System.ComponentModel;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the AI:ApiKey configuration value or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();

// Define the tools the agent can use
var tools = new ResearchTools();

var agent = new ChatClientAgent(
    chatClient,
    "ResearchAgent",
    "You are a research assistant. Use the web_search tool to find information about the given topic. "
    + "Use the take_note tool to record important findings. Search multiple queries to build a comprehensive understanding. "
    + "After gathering enough information, provide a final summary of your findings.",
    [AIFunctionFactory.Create(tools.WebSearch), AIFunctionFactory.Create(tools.TakeNote)]);

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine();

if (tools.Notes.Count > 0)
{
    Console.WriteLine("\n=== Research Notes ===");
    foreach (var note in tools.Notes)
    {
        Console.WriteLine($"• {note}");
    }
}

/// <summary>
/// Tools available to the research agent.
/// </summary>
sealed class ResearchTools
{
    public List<string> Notes { get; } = [];

    [Description("Search the web for information on a query. Returns search result snippets.")]
    public string WebSearch([Description("The search query")] string query)
    {
        // Simulated web search results — replace with a real search API (e.g., Bing Search) in production.
        Console.WriteLine($"  [Tool] Searching: \"{query}\"");
        return query.ToLowerInvariant() switch
        {
            var q when q.Contains("quantum computing") =>
                "Results for quantum computing:\n"
                + "1. Quantum computing uses qubits that can exist in superposition states.\n"
                + "2. Major players include IBM, Google, and Microsoft with different qubit technologies.\n"
                + "3. Google achieved quantum supremacy in 2019 with their Sycamore processor.\n"
                + "4. Practical applications include cryptography, drug discovery, and optimization problems.\n"
                + "5. Current challenges include error correction and maintaining qubit coherence.",
            var q when q.Contains("climate") =>
                "Results for climate:\n"
                + "1. Global temperatures have risen ~1.1°C since pre-industrial times.\n"
                + "2. The Paris Agreement aims to limit warming to 1.5°C.\n"
                + "3. Renewable energy adoption is accelerating worldwide.\n"
                + "4. Key impacts include sea level rise, extreme weather events, and biodiversity loss.\n"
                + "5. Carbon capture technologies are emerging as potential mitigation tools.",
            _ =>
                $"Results for \"{query}\":\n"
                + $"1. {query} is an active area of research and development.\n"
                + $"2. Recent advancements in {query} have shown promising results.\n"
                + $"3. Experts predict significant growth in {query} over the next decade.\n"
                + $"4. Key challenges include scalability, cost, and public awareness.\n"
                + $"5. Multiple organizations are investing heavily in {query} research."
        };
    }

    [Description("Take a note to record an important finding during research.")]
    public string TakeNote([Description("The note content to save")] string note)
    {
        Notes.Add(note);
        Console.WriteLine($"  [Tool] Note saved: \"{note[..Math.Min(note.Length, 60)]}...\"");
        return $"Note saved successfully. Total notes: {Notes.Count}";
    }
}

